input.command:
cd /home/experimenter/experiments/runs/2026-09-23_16-45-13_claim-office-example-mapping_exact-ptdd-v1.1-refactor-subagent-cc_opus-5-5-no-thinking; cat > src/claimOffice.ts <<'EOF'
export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioOutput {
  results: object[];
}

const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const PROCESSING_FEE = 5;

function quotePremium(items: Item[]): number {
  const policyBasePremium = items.length * SWORD_BASE_PREMIUM;
  const premium = policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
