import type { Damage, Item } from "./claimOffice.js";
import * as priceList from "./priceList.js";

const CAP_MULTIPLIER = 2;
const DEDUCTIBLE = 100;

export interface Policy {
  remainingCap: number;
}

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + priceList.insuranceValue(item.type), 0);
}

export function openPolicy(items: Item[]): Policy {
  return { remainingCap: CAP_MULTIPLIER * insuranceSum(items) };
}

function damagePayout(damage: Damage): number {
  return damage.amount - DEDUCTIBLE;
}

function claimPayout(damages: Damage[]): number {
  return damages.reduce((sum, damage) => sum + damagePayout(damage), 0);
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export function processClaim(policy: Policy, damages: Damage[]): ClaimResult {
  const payout = claimPayout(damages);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
interface Price {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEM_PRICES: Record<string, Price> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_PRICE: Price = { insuranceValue: 250, basePremium: 25 };

const PRICE_LIST: Record<string, Price> = {
  ...MAIN_ITEM_PRICES,
  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_PRICE])),
};

export function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

export function insuranceValue(type: string): number {
  return PRICE_LIST[type].insuranceValue;
}

export function basePremium(type: string): number {
  return PRICE_LIST[type].basePremium;
}

